-- HostelOS Single-Transaction Seed for Supabase / PostgreSQL
BEGIN;

-- Partial Unique Indexes for Single Bed Allocation
CREATE UNIQUE INDEX IF NOT EXISTS idx_allocations_active_student ON public.allocations (student_id) WHERE is_active = TRUE;
CREATE UNIQUE INDEX IF NOT EXISTS idx_allocations_active_bed ON public.allocations (room_number, bed_number) WHERE is_active = TRUE;

-- Wipe old records but preserve admin and warden
DELETE FROM public.allocations;
DELETE FROM public.rooms;
DELETE FROM public.blocks;
DELETE FROM public.profiles WHERE role = 'student';
DELETE FROM public.complaints;
DELETE FROM public.fees;
DELETE FROM public.notices;


COMMIT;